#' Desirability of Outcome Ranking (DOOR)
#'
#' Compares two groups on an ordinal Desirability of Outcome Ranking (DOOR), a 
#' composite that ranks each patient by overall clinical desirability 
#' combining efficacy and safety. The DOOR probability is the chance that a 
#' randomly chosen patient from the index group has a more desirable outcome 
#' than a randomly chosen patient from the reference group (ties split evenly) 
#' - equivalent to a Mann-Whitney / AUC estimand. Values above 0.5 favour the 
#' index group. This approach, developed for antimicrobial and benefit-risk 
#' trials, avoids collapsing outcomes of differing severity into a single 
#' binary endpoint.
#' 
#' @param data The data as a data frame (one row per subject).
#' @param group Two-level group variable.
#' @param refLevel The level of the group variable to treat as the reference.
#'   The DOOR probability expresses the chance the other (index) group is more
#'   desirable.
#' @param doorRank Ordinal DOOR category for each subject. Combined with the
#'   ranking direction to determine which outcomes are more desirable.
#' @param rankDirection Whether a lower or higher DOOR category value
#'   represents the more desirable outcome.
#' @param conf_level Confidence level for the DOOR probability interval.
#' @param showDistribution Display the distribution of DOOR categories within
#'   each group.
#' @param showPlot Display a stacked bar of DOOR category proportions by
#'   group.
#' @param showSummary Display a plain-language summary of the DOOR
#'   probability.
#' @param showExplanation Display an explanation of the DOOR methodology.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$mainTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$distributionTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$mainTable$asDF}
#'
#' \code{as.data.frame(results$mainTable)}
#'
#' @export
door <- function(
    data,
    group,
    refLevel,
    doorRank,
    rankDirection = "lower",
    conf_level = 0.95,
    showDistribution = TRUE,
    showPlot = TRUE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("door requires jmvcore to be installed (restart may be required)")

    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(doorRank)) doorRank <- jmvcore::resolveQuo(jmvcore::enquo(doorRank))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(doorRank), doorRank, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- doorOptions$new(
        group = group,
        refLevel = refLevel,
        doorRank = doorRank,
        rankDirection = rankDirection,
        conf_level = conf_level,
        showDistribution = showDistribution,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- doorClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

